// Shipped workspace + Firebase adapter; draft envelopes generated by the real
// handler. Controlled auth/network boundaries; no production writes or emails.
import {completionGuard} from './_complete.mjs';
const {finish}=completionGuard('draft-read-workflow-browser');
import {readFileSync,existsSync} from 'node:fs';
import {resolve,extname} from 'node:path';
import {createServer} from 'node:http';
import {chromium} from 'playwright';
import {generateFixtures,generateReadFixtures} from './_draftListFixtures.mjs';
import {publicMembershipCatalogue} from '../api/_membershipPurchaseRoutes.js';
const F=await generateFixtures(),R=await generateReadFixtures();
const root=resolve(new URL('../',import.meta.url).pathname);
const server=createServer((req,res)=>{
 const pathname=new URL(req.url,'http://local').pathname;
 const file=resolve(root,'.'+(pathname==='/'?'/index.html':pathname));
 if(!file.startsWith(root+'/')||!existsSync(file)){res.writeHead(404).end();return;}
 res.setHeader('Content-Type',({'.js':'text/javascript','.html':'text/html','.css':'text/css','.json':'application/json'})[extname(file)]||'application/octet-stream');res.end(readFileSync(file));
});await new Promise(r=>server.listen(0,'127.0.0.1',r));
const origin='http://127.0.0.1:'+server.address().port;
const sdk=`export const initializeAuth=()=>window.fixtureAuth;
export function onAuthStateChanged(auth,fn){window.fixtureListener=fn;queueMicrotask(()=>fn(auth.currentUser));}
export const signOut=async()=>window.emitFixtureUser(null);
export class GoogleAuthProvider {setCustomParameters(){}}
export const signInWithPopup=async()=>{},createUserWithEmailAndPassword=async()=>{},signInWithEmailAndPassword=async()=>{},sendPasswordResetEmail=async()=>{},sendEmailVerification=async()=>{};
export const indexedDBLocalPersistence={},browserLocalPersistence={},browserSessionPersistence={},browserPopupRedirectResolver={};`;
const browser=await chromium.launch({executablePath:process.env.CR_CHROMIUM,args:['--no-sandbox']});
let passed=0;const failures=[];
const check=(ok,label)=>{if(ok)passed++;else failures.push(label);};
const deferred=()=>{let resolve;const promise=new Promise(r=>resolve=r);return {promise,resolve};};
try{
 for(const width of [390,1280]){
  const page=await browser.newPage({viewport:{width,height:1000}}),errors=[],calls=[];
  page.on('pageerror',e=>errors.push(e.message));
  let listPlan=uid=>uid==='alice'?F.page1:F.empty,readPlan=id=>id===R.ids.packetShipDeclared?R.packetShipDeclared:R.packetCurrent,patchPlan=()=>({status:200,body:{ok:true}});
  await page.route('**/*',async route=>{
   const req=route.request(),url=new URL(req.url());
   if(url.hostname==='www.gstatic.com'&&url.pathname.endsWith('/firebase-app.js'))return route.fulfill({contentType:'text/javascript',body:'export const initializeApp=()=>({});'});
   if(url.hostname==='www.gstatic.com'&&url.pathname.endsWith('/firebase-auth.js'))return route.fulfill({contentType:'text/javascript',body:sdk});
   if(url.origin!==origin)return route.fulfill({status:204,body:''});
   if(!url.pathname.startsWith('/api/'))return route.continue();
   const uid=(req.headers().authorization||'').replace('Bearer local-','');
   if(url.pathname==='/api/membership-catalogue')return route.fulfill({json:{...publicMembershipCatalogue(),purchaseEnabled:false}});
   if(url.pathname==='/api/pro-status')return route.fulfill({json:{isPro:true,tier:'business',emailVerified:true,idPaidLeft:12,idFreeLeft:0}});
   if(url.pathname==='/api/drafts'){
    calls.push({uid,method:req.method(),id:url.searchParams.get('id'),cursor:url.searchParams.get('cursor')});
    const out=await (req.method()==='PATCH'?patchPlan():url.searchParams.has('id')?readPlan(url.searchParams.get('id')):listPlan(uid,url.searchParams));
    try{return await route.fulfill({status:out.status,json:out.body});}catch{return;}
   }
   return route.fulfill({status:503,json:{error:'offline_fixture'}});
  });
  await page.addInitScript(()=>{
   localStorage.setItem('cs_landing_seen','1');window.fixtureAuth={currentUser:null};
   const original=setTimeout;window.setTimeout=(fn,ms,...args)=>original(fn,ms===15000?180:ms,...args);
   window.makeFixtureUser=uid=>({uid,email:uid+'@example.invalid',displayName:uid,emailVerified:true,providerData:[{providerId:'password'}],reload:async()=>{},getIdToken:async()=> 'local-'+uid});
   window.emitFixtureUser=user=>{fixtureAuth.currentUser=user;return fixtureListener(user);};
  });
  await page.goto(origin+'/index.html');await page.waitForFunction(()=>typeof fixtureListener==='function'&&typeof loadDraftsFirstPage==='function');await page.waitForTimeout(300);
  await page.evaluate(()=>emitFixtureUser(makeFixtureUser('alice')));await page.waitForFunction(()=>_googleIdToken==='local-alice');
  await page.evaluate(()=>switchView('drafts'));await page.waitForFunction(()=>!_draftsState.loading&&_draftsState.rows.length>0);
  check(await page.locator('#draftsWrap .draft-row').count()===F.page1.body.rows.length,'saved drafts render at '+width);
  check(await page.locator('#draftsMoreBtn').isEnabled(),'pagination is available at '+width);

  const stalled=deferred();listPlan=()=>stalled.promise;
  await page.evaluate(()=>{void loadDraftsFirstPage();});await page.locator('#draftsRetryBtn').waitFor();
  check((await page.locator('#draftsWrap').innerText()).includes('Loading took too long'),'timeout explains recovery at '+width);
  check(await page.locator('#draftsRetryBtn').isEnabled(),'timeout enables a deliberate retry at '+width);
  check(await page.locator('#draftsWrap [aria-label="Loading your drafts"]').count()===0,'timeout removes the spinner at '+width);
  if(process.env.CR_SHOT_DIR)await page.screenshot({path:resolve(process.env.CR_SHOT_DIR,'draft-timeout-'+width+'.png')});
  listPlan=()=>F.empty;await page.locator('#draftsRetryBtn').click();await page.waitForFunction(()=>!_draftsState.loading&&_draftsState.total===0);
  stalled.resolve(F.page1);await page.waitForTimeout(60);
  check(await page.locator('#draftsWrap .draft-row').count()===0,'late timed-out page cannot replace retry at '+width);

  const oldPage=deferred();listPlan=()=>oldPage.promise;await page.evaluate(()=>{void loadDraftsFirstPage();});
  await page.waitForTimeout(20);listPlan=()=>F.empty;await page.evaluate(()=>loadDraftsFirstPage());oldPage.resolve(F.page1);await page.waitForTimeout(40);
  check(await page.evaluate(()=>_draftsState.total===0&&!_draftsState.rows.length),'newest list request wins at '+width);

  listPlan=()=>F.page1;await page.evaluate(()=>loadDraftsFirstPage());listPlan=()=>({status:503,body:{error:'Temporary offline fixture',retryable:true}});
  await page.locator('#draftsMoreBtn').click();await page.waitForFunction(()=>!_draftsState.loading);
  check(await page.locator('#draftsWrap .draft-row').count()===F.page1.body.rows.length,'failed pagination preserves visible drafts at '+width);
  check(await page.locator('#draftsMoreBtn').isEnabled(),'failed pagination keeps Load more usable at '+width);
  listPlan=()=>({status:401,body:{}});await page.locator('#draftsMoreBtn').click();await page.waitForFunction(()=>!_draftsState.loading);
  check((await page.locator('#draftsWrap').innerText()).includes('Sign in to see your drafts'),'expired pagination shows sign-in recovery at '+width);
  check(await page.locator('#draftsWrap .draft-row').count()===0&&!await page.locator('#colSubDraftsCount').textContent(),'expired pagination clears private rows and badge at '+width);

  const oldAccount=deferred();listPlan=uid=>uid==='alice'?oldAccount.promise:F.empty;await page.evaluate(()=>{void loadDraftsFirstPage();});await page.waitForTimeout(20);
  await page.evaluate(()=>emitFixtureUser(makeFixtureUser('bob')));await page.waitForFunction(()=>!_draftsState.loading&&_draftsState.total===0);
  oldAccount.resolve(F.page1);await page.waitForTimeout(50);
  check(await page.evaluate(()=>googleUser.uid==='bob'&&!_draftsState.rows.length),'old response cannot reveal another seller drafts at '+width);
  check(await page.locator('#draftsWrap .draft-row').count()===0,'new account has its own draft list at '+width);

  listPlan=()=>F.page1;await page.evaluate(()=>emitFixtureUser(makeFixtureUser('alice')));await page.waitForFunction(()=>!_draftsState.loading&&_draftsState.rows.length>0);
  await page.evaluate(id=>openDraftReview(id),R.ids.packetCurrent);await page.waitForFunction(()=>!_reviewState.loading&&!!_reviewState.draft);
  check(await page.locator('#reviewView').isVisible(),'draft review opens at '+width);
  check(await page.locator('.review-verdict-ok').evaluate(el=>getComputedStyle(el).color===getComputedStyle(document.documentElement).getPropertyValue('--green').trim()||getComputedStyle(el).color==='rgb(46, 122, 64)'),'ready verdict uses readable theme green at '+width);
  const oldRefresh=deferred();patchPlan=()=>oldRefresh.promise;
  await page.evaluate(()=>{void _reviewRefreshPacket();});await page.waitForFunction(()=>_reviewState.refreshing);
  await page.evaluate(id=>openDraftReview(id),R.ids.packetShipDeclared);await page.waitForFunction(()=>!_reviewState.loading&&!!_reviewState.draft);
  oldRefresh.resolve({status:200,body:{ok:true}});await page.waitForTimeout(70);
  check(await page.evaluate(id=>_reviewState.draftId===id&&_reviewState.draft?.draftId===id,R.ids.packetShipDeclared),'late refresh cannot reopen the old draft at '+width);
  if(process.env.CR_SHOT_DIR)await page.screenshot({path:resolve(process.env.CR_SHOT_DIR,'draft-review-'+width+'.png')});
  await page.evaluate(()=>emitFixtureUser(null));
  check((await page.locator('#reviewWrap').innerText()).includes('Sign in to see this draft'),'SDK sign-out clears the visible review at '+width);
  check(await page.evaluate(()=>!_reviewState.draft&&!_reviewState.packet&&!_reviewState.draftId&&!_draftsState.rows.length),'sign-out clears review data and copy payloads at '+width);
  check(await page.locator('#reviewWrap [data-packet-copy]').count()===0,'sign-out removes copy controls at '+width);
  listPlan=()=>F.empty;await page.evaluate(()=>emitFixtureUser(makeFixtureUser('bob')));await page.waitForFunction(()=>!_draftsState.loading&&_draftsState.total===0);
  check(await page.locator('#draftsView').isVisible(),'new account returns to its draft list at '+width);
  check(calls.filter(c=>c.uid==='bob'&&c.id).length===0,'new account never requests the previous seller draft ID at '+width);
  check(errors.length===0,'no uncaught browser errors at '+width+': '+errors.join('; '));
  check(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'draft workflow fits viewport at '+width);
  await page.close();
 }
}finally{await browser.close();await new Promise(r=>server.close(r));}
for(const failure of failures)console.error('FAIL:',failure);
finish(passed,failures.length);
